package workbook.product; import java.sql.*;import java.util.*;import workbook.common.DBConnection; public class ProductDAO {
public List<Product> findAll()throws SQLException{List<Product>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT product_id,product_name,price,stock FROM product ORDER BY product_id");ResultSet r=p.executeQuery()){while(r.next())a.add(new Product(r.getString(1),r.getString(2),r.getInt(3),r.getInt(4)));}return a;}
public int insert(Product m)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO product VALUES(?,?,?,?)")){p.setString(1,m.productId());p.setString(2,m.productName());p.setInt(3,m.price());p.setInt(4,m.stock());return p.executeUpdate();}}
public int update(Product m)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE product SET product_name=?,price=?,stock=? WHERE product_id=?")){p.setString(1,m.productName());p.setInt(2,m.price());p.setInt(3,m.stock());p.setString(4,m.productId());return p.executeUpdate();}}
public int delete(String id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM product WHERE product_id=?")){p.setString(1,id);return p.executeUpdate();}}}